* { box-sizing: border-box; }
html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #78a7ff;
  font-family: "Courier New", monospace;
}
canvas { display: block; }
#game {
  position: fixed;
  inset: 0;
  z-index: 0;
  cursor: crosshair;
}
#ui {
  position: fixed;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
}
#loading {
  position: fixed;
  inset: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #1b1b1b;
  background-image: url('/mc/textures/block/dirt.png');
  background-size: 64px 64px;
  image-rendering: pixelated;
  color: #ddd;
}
#loading.hidden { display: none; }
#loading .panel {
  width: min(560px, 84vw);
  padding: 26px 30px 22px;
  background: rgba(12, 12, 12, 0.82);
  border: 2px solid #3a3a3a;
  box-shadow: 0 0 0 4px rgba(0, 0, 0, 0.25);
  text-align: center;
}
#loading .logo {
  font-size: 30px;
  font-weight: bold;
  letter-spacing: 4px;
  color: #fff;
  text-shadow: 3px 3px 0 #3a3a3a;
}
#loading .sub {
  margin-top: 6px;
  font-size: 12px;
  color: #9a9a9a;
  letter-spacing: 1px;
}
#loading .bar {
  margin: 22px auto 10px;
  height: 12px;
  width: 100%;
  background: #222;
  border: 2px solid #555;
}
#loading-bar {
  width: 0%;
  height: 100%;
  background: #61b34a;
  transition: width 0.12s linear;
}
#loading-label {
  font-size: 12px;
  min-height: 16px;
  color: #cfcfcf;
}
#loading .note {
  margin-top: 18px;
  font-size: 10px;
  line-height: 1.6;
  color: #777;
}
body.ready #loading { display: none; }

