6	 * Auto-enables on touch hardware or ?touch=1; setVisible(false) while a
7	 * menu/inventory/pause screen is open, and setFlying() to reveal fly buttons.
8	 */
9	
10	export interface TouchControlOptions {
11	  /** Auto-enable on touch devices. Defaults to isTouchDevice(). */
12	  autoEnable?: boolean;
13	  /** Initial visibility once enabled. Default true. */
14	  visible?: boolean;
15	  /** Multiplies consumeLook() deltas (CSS pixels). Default 1. */
16	  sensitivity?: number;
