48	
49	/** True on coarse-pointer/mobile devices, or when the URL has touch=1. */
50	export function isTouchDevice(): boolean {
51	  if (typeof window === 'undefined') return false;
52	  let forced: string | null = null;
53	  try {
54	    forced = new URLSearchParams(window.location.search).get('touch');
55	  } catch {
56	    forced = null;
