/*
 * TouchControls overlay styles (see touch.ts).
 * Fixed-position overlay only: no layout shift, and pointer-events are enabled
 * per control surface so the page stays usable when controls are hidden.
 */

.tc-root {
  --tc-safe-top: env(safe-area-inset-top, 0px);
  --tc-safe-right: env(safe-area-inset-right, 0px);
  --tc-safe-bottom: env(safe-area-inset-bottom, 0px);
  --tc-safe-left: env(safe-area-inset-left, 0px);

  /* Replaced from JS with the HUD's real hotbar height (22 * guiScale). */
  --tc-hotbar: 44px;

  --tc-joy: 112px;
  --tc-nub: 46px;
  --tc-lg: 66px;
  --tc-md: 56px;
  --tc-sm: 46px;
  --tc-util: 34px;
  --tc-gap: 8px;
  --tc-cluster-w: calc(var(--tc-sm) + var(--tc-gap) + var(--tc-lg) + var(--tc-gap) + var(--tc-lg));
  --tc-cluster-h: calc(var(--tc-util) + 8px + var(--tc-md) + var(--tc-gap) + var(--tc-lg));

  --tc-glass: rgba(18, 18, 20, 0.42);
  --tc-glass-strong: rgba(18, 18, 20, 0.58);
  --tc-edge: rgba(255, 255, 255, 0.72);

  position: fixed;
  inset: 0;
  z-index: 6;
  pointer-events: none; /* only the control surfaces opt back in */
  opacity: 0;
  visibility: hidden;
  transition: opacity 160ms ease, visibility 0s linear 160ms;
  user-select: none;
  -webkit-user-select: none;
  -webkit-touch-callout: none;
  -webkit-tap-highlight-color: transparent;
  font-family: "Courier New", monospace;

  /* The game renders underneath; this overlay is paint-only. */
  overflow: hidden;
  contain: layout style;
}

.tc-root[data-enabled="true"][data-visible="true"] {
  opacity: 1;
  visibility: visible;
  transition: opacity 200ms ease, visibility 0s linear 0s;
}

/* ------------------------------------------------------------------ look region */

.tc-look {
  position: absolute;
  left: 50%;
  right: var(--tc-safe-right);
  top: var(--tc-safe-top);
  bottom: calc(var(--tc-safe-bottom) + var(--tc-hotbar) + 12px);
  pointer-events: none;
  touch-action: none;
  cursor: crosshair;
  z-index: 0;
}

/* ------------------------------------------------------------------ joystick */

.tc-joy {
  position: absolute;
  left: calc(var(--tc-safe-left) + 18px);
  bottom: calc(var(--tc-safe-bottom) + var(--tc-hotbar) + 14px);
  width: var(--tc-joy);
  height: var(--tc-joy);
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.38);
  background:
    radial-gradient(circle at 50% 44%, rgba(255, 255, 255, 0.09), rgba(8, 8, 10, 0.34) 72%),
    rgba(8, 8, 10, 0.12);
  box-shadow:
    0 0 0 1px rgba(0, 0, 0, 0.22),
    inset 0 0 22px rgba(0, 0, 0, 0.3);
  pointer-events: none;
  touch-action: none;
  z-index: 1;
  transition: border-color 120ms ease, background-color 120ms ease;
}

.tc-joy::before {
  content: "";
  position: absolute;
  inset: 17%;
  border-radius: 50%;
  border: 1px dashed rgba(255, 255, 255, 0.14);
  pointer-events: none;
}

.tc-joy.is-active {
  border-color: rgba(255, 255, 255, 0.62);
  background:
    radial-gradient(circle at 50% 44%, rgba(255, 255, 255, 0.13), rgba(8, 8, 10, 0.4) 72%),
    rgba(8, 8, 10, 0.18);
}

.tc-joy-nub {
  position: absolute;
  left: 50%;
  top: 50%;
  width: var(--tc-nub);
  height: var(--tc-nub);
  margin: calc(var(--tc-nub) / -2) 0 0 calc(var(--tc-nub) / -2);
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.82);
  background:
    radial-gradient(circle at 36% 30%, rgba(255, 255, 255, 0.32), rgba(30, 30, 34, 0.62) 74%);
  box-shadow:
    0 2px 8px rgba(0, 0, 0, 0.38),
    inset 0 0 10px rgba(0, 0, 0, 0.25);
  transition: transform 140ms cubic-bezier(0.2, 0.8, 0.3, 1);
  will-change: transform;
  pointer-events: none;
}

.tc-joy-nub::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  width: 5px;
  height: 5px;
  margin: -2.5px 0 0 -2.5px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.5);
}

.tc-joy.is-active .tc-joy-nub {
  transition: none;
}

.tc-joy.is-sprinting .tc-joy-nub {
  border-color: rgba(178, 244, 156, 0.95);
  box-shadow:
    0 0 10px rgba(150, 238, 120, 0.35),
    0 2px 8px rgba(0, 0, 0, 0.38),
    inset 0 0 10px rgba(0, 0, 0, 0.25);
}

/* ------------------------------------------------------------------ action cluster */

.tc-cluster {
  position: absolute;
  right: calc(var(--tc-safe-right) + 10px);
  bottom: calc(var(--tc-safe-bottom) + var(--tc-hotbar) + 12px);
  width: var(--tc-cluster-w);
  height: var(--tc-cluster-h);
  pointer-events: none;
  touch-action: none;
  z-index: 2;
}

.tc-utils {
  position: absolute;
  top: 0;
  right: 0;
  display: flex;
  gap: 6px;
}

.tc-btn {
  position: absolute;
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--tc-md);
  height: var(--tc-md);
  padding: 0;
  border-radius: 50%;
  border: 2px solid var(--tc-edge);
  background: var(--tc-glass);
  color: #fff;
  box-shadow:
    0 2px 7px rgba(0, 0, 0, 0.34),
    inset 0 0 12px rgba(0, 0, 0, 0.22);
  touch-action: none;
  cursor: pointer;
  outline: none;
  -webkit-user-select: none;
  user-select: none;
  -webkit-user-drag: none;
  transform: scale(1);
  transition:
    transform 90ms ease,
    background-color 90ms ease,
    border-color 90ms ease,
    box-shadow 90ms ease,
    opacity 130ms ease;
}

.tc-btn svg {
  width: 56%;
  height: 56%;
  fill: none;
  stroke: #fff;
  stroke-width: 2.4;
  stroke-linecap: round;
  stroke-linejoin: round;
  filter: drop-shadow(0 1px 1px rgba(0, 0, 0, 0.55));
  pointer-events: none;
}

.tc-btn-pause svg {
  stroke-width: 3.6;
}

.tc-btn.is-pressed {
  background: rgba(255, 255, 255, 0.26);
  border-color: #fff;
  box-shadow:
    0 0 0 3px rgba(255, 255, 255, 0.13),
    inset 0 0 14px rgba(255, 255, 255, 0.14);
  transform: scale(0.92);
}

@media (hover: hover) and (pointer: fine) {
  .tc-btn:hover {
    background: rgba(255, 255, 255, 0.17);
    border-color: rgba(255, 255, 255, 0.9);
  }
}

/* primary */
.tc-btn-jump {
  right: 0;
  bottom: 0;
  width: var(--tc-lg);
  height: var(--tc-lg);
}

.tc-btn-attack {
  right: calc(var(--tc-lg) + var(--tc-gap));
  bottom: 0;
  width: var(--tc-lg);
  height: var(--tc-lg);
  background: rgba(58, 22, 22, 0.42);
}

.tc-btn-attack.is-pressed {
  background: rgba(255, 255, 255, 0.26);
}

/* secondary */
.tc-btn-use {
  right: calc(var(--tc-lg) + var(--tc-gap));
  bottom: calc(var(--tc-lg) + var(--tc-gap));
  width: var(--tc-md);
  height: var(--tc-md);
}

.tc-btn-sneak {
  right: 0;
  bottom: calc(var(--tc-lg) + var(--tc-gap));
  width: var(--tc-md);
  height: var(--tc-md);
}

/* flight-only, hidden by default so no layout shift occurs */
.tc-btn-fly {
  right: calc(var(--tc-lg) * 2 + var(--tc-gap) * 2);
  width: var(--tc-sm);
  height: var(--tc-sm);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 120ms ease, visibility 0s linear 120ms, transform 90ms ease, background-color 90ms ease;
}

.tc-btn-fly-up {
  bottom: calc(var(--tc-lg) + 4px);
}

.tc-btn-fly-down {
  bottom: 6px;
}

/* utilities */
.tc-utils .tc-btn {
  position: relative;
  width: var(--tc-util);
  height: var(--tc-util);
  border-width: 1.5px;
  background: rgba(18, 18, 20, 0.34);
  box-shadow: 0 1px 5px rgba(0, 0, 0, 0.28);
}

.tc-utils .tc-btn svg {
  width: 54%;
  height: 54%;
  stroke-width: 2.2;
}

/* ------------------------------------------------------------------ enabled state */

.tc-root[data-enabled="true"][data-visible="true"] .tc-look,
.tc-root[data-enabled="true"][data-visible="true"] .tc-joy,
.tc-root[data-enabled="true"][data-visible="true"] .tc-cluster {
  pointer-events: auto;
}

.tc-root[data-enabled="true"][data-visible="true"] .tc-btn-fly {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.tc-root[data-enabled="true"][data-visible="true"][data-flying="true"] .tc-btn-fly {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transition: opacity 120ms ease, visibility 0s linear 0s, transform 90ms ease, background-color 90ms ease;
}

.tc-root[data-underwater="true"] .tc-btn-jump {
  border-color: rgba(168, 226, 255, 0.9);
}

.tc-root[data-underwater="true"] .tc-btn-jump svg {
  stroke: #c6ecff;
}

/* ------------------------------------------------------------------ responsive layout */

/* Portrait: joystick lower-left, compact cluster lower-right above the hotbar. */
@media (orientation: portrait) {
  .tc-joy {
    left: calc(var(--tc-safe-left) + 20px);
    bottom: calc(var(--tc-safe-bottom) + var(--tc-hotbar) + 18px);
  }

  .tc-cluster {
    right: calc(var(--tc-safe-right) + 8px);
    bottom: calc(var(--tc-safe-bottom) + var(--tc-hotbar) + 18px);
  }
}

@media (max-width: 380px) {
  .tc-root {
    --tc-joy: 100px;
    --tc-nub: 42px;
    --tc-lg: 58px;
    --tc-md: 50px;
    --tc-sm: 42px;
    --tc-util: 30px;
    --tc-gap: 7px;
  }
}

@media (max-height: 430px) {
  .tc-root {
    --tc-joy: 96px;
    --tc-nub: 40px;
    --tc-lg: 54px;
    --tc-md: 46px;
    --tc-sm: 38px;
    --tc-util: 30px;
    --tc-gap: 7px;
  }
}

/* Very short landscape screens: keep the joystick clear of the debug text. */
@media (max-height: 360px) {
  .tc-root {
    --tc-joy: 84px;
    --tc-nub: 36px;
    --tc-lg: 50px;
    --tc-md: 42px;
